def validate_record(record):
    if 'id' not in record or 'amount' not in record:
        raise ValueError("Record must contain 'id' and 'amount' fields.")
    return True

def normalize_amount(records):
    normalized_records = []
    for record in records:
        amount = record.get('amount', 0)
        if not isinstance(amount, (int, float)):
            amount = 0
        amount = max(0, min(amount, 1000000))
        record['amount'] = amount
        normalized_records.append(record)
    return normalized_records

def dedupe_records(records):
    seen_ids = set()
    unique_records = []
    for record in records:
        if 'id' not in record:
            continue
        if record['id'] not in seen_ids:
            seen_ids.add(record['id'])
            unique_records.append(record)
    return unique_records

def retry_failed(fn, attempts):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception:
            if attempt == attempts - 1:
                raise
    return None

def process_with_retry(records, attempts=3):
